INSERT INTO `wp_options` VALUES (2285,'rank_math_notifications','a:2:{i:0;a:2:{s:7:\"message\";s:247:\"Rank Math has detected a new post type: <code>reco_listing</code>. You may want to check the settings of the <a href=\"http://reco-group.local/wp-admin/admin.php?page=rank-math-options-titles&view=post-type-reco_listing\">Titles &amp; Meta page</a>.\";s:7:\"options\";a:5:{s:2:\"id\";s:13:\"new_post_type\";s:7:\"classes\";s:16:\"rank-math-notice\";s:4:\"type\";s:4:\"info\";s:6:\"screen\";s:3:\"any\";s:10:\"capability\";s:0:\"\";}}i:1;a:2:{s:7:\"message\";s:839:\"<p>Hey, we noticed you&#039;ve been using <strong>Rank Math SEO</strong> for more than a week now – that&#039;s awesome!<br>We would love to get your feedback! It&#039;s essential for our continued development. Please consider taking a moment to leave us a review.</p>\n			<p><strong>Bhanu Ahluwalia</strong><br>Co-founder of Rank Math</p>\n			<p>\n				<a href=\"https://wordpress.org/support/plugin/seo-by-rank-math/reviews/?filter=5#new-post\" class=\"rank-math-dismiss-review-notice rank-math-review-action rank-math-review-out\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Yes, you deserve it</strong></a><br>\n				<a href=\"#\" class=\"rank-math-dismiss-review-notice rank-math-maybe-later-action\">No, maybe later</a><br>\n				<a href=\"#\" class=\"rank-math-dismiss-review-notice rank-math-already-reviewed-action\">I already did</a>\n			</p>\";s:7:\"options\";a:5:{s:2:\"id\";s:30:\"rank_math_review_plugin_notice\";s:7:\"classes\";s:16:\"rank-math-notice\";s:4:\"type\";s:4:\"info\";s:6:\"screen\";s:3:\"any\";s:10:\"capability\";s:15:\"install_plugins\";}}}','auto');
